"""Configuration backup and restore web service.

A small Flask application for creating, listing, and restoring gzipped
tar archives of the application's configuration directory.
"""

import os
import secrets
import tarfile
from dataclasses import dataclass

from flask import Flask, abort, flash, redirect, render_template, request
from werkzeug.utils import secure_filename

# ---------------------------------------------------------------------------
# Named constants
# ---------------------------------------------------------------------------

DEFAULT_BACKUP_DIR = '/var/backups/configs'
DEFAULT_CONFIG_DIR = '/etc/appconfigs'

BACKUP_ARCHIVE_SUFFIX = '.tar.gz'
DEFAULT_BACKUP_NAME = 'config_backup'
MAX_BACKUP_SIZE_BYTES = 10 * 1024 * 1024  # 10 MiB
FORBIDDEN_FILENAME_TOKENS = ('../', '~')

SECRET_KEY_BYTES = 32

DIRECTORY_MODE = 0o750
CONFIG_FILE_MODE = 0o640

SAMPLE_CONFIG_COUNT = 3
SAMPLE_CONFIG_NAME_TEMPLATE = 'config{index}.ini'
SAMPLE_CONFIG_CONTENTS_TEMPLATE = '[DEFAULT]\nsetting{index} = value{index}\n'

SERVER_HOST = '0.0.0.0'
SERVER_PORT = 8080

MSG_BACKUP_DIR_ERROR = 'Error accessing backup directory'
MSG_INVALID_BACKUP_NAME = 'Invalid backup name'
MSG_BACKUP_TOO_LARGE = 'Backup too large'
MSG_BACKUP_CREATED = 'Backup created successfully'
MSG_BACKUP_FAILED = 'Backup failed'
MSG_RESTORE_SUCCESS = 'Configuration restored successfully'
MSG_INVALID_BACKUP_FILE = 'Invalid backup file'
MSG_INVALID_BACKUP_FORMAT = 'Invalid backup file format'
MSG_BACKUP_NOT_FOUND = 'Backup file not found'
MSG_ACCESS_DENIED = 'Access denied'
MSG_INVALID_BACKUP_CONTENTS = 'Invalid backup contents'
MSG_RESTORE_FAILED = 'Restoration failed'
MSG_NOT_FOUND = 'Resource not found'
MSG_BAD_REQUEST = 'Invalid request'
MSG_SERVER_ERROR = 'Internal server error'

INDEX_ROUTE = '/'
CREATE_BACKUP_ROUTE = '/create_backup'
RESTORE_BACKUP_ROUTE = '/restore_backup/<backup_file>'


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class BackupServiceConfig:
    """Filesystem locations and size limits used by the backup service."""

    backup_dir: str
    config_dir: str
    max_backup_size: int

    @classmethod
    def default(cls):
        """Build the standard configuration."""
        return cls(
            backup_dir=os.path.abspath(DEFAULT_BACKUP_DIR),
            config_dir=os.path.abspath(DEFAULT_CONFIG_DIR),
            max_backup_size=MAX_BACKUP_SIZE_BYTES,
        )


CONFIG = BackupServiceConfig.default()

app = Flask(__name__)


def configure_app(flask_app, config):
    """Apply a :class:`BackupServiceConfig` to a Flask application."""
    flask_app.secret_key = secrets.token_hex(SECRET_KEY_BYTES)
    flask_app.config['BACKUP_DIR'] = config.backup_dir
    flask_app.config['CONFIG_DIR'] = config.config_dir
    flask_app.config['MAX_BACKUP_SIZE'] = config.max_backup_size


configure_app(app, CONFIG)


# ---------------------------------------------------------------------------
# Path and filename validation helpers
# ---------------------------------------------------------------------------

def is_safe_path(base_path, requested_path):
    """Return True when ``requested_path`` resolves inside ``base_path``."""
    base_path = os.path.abspath(base_path)
    requested_path = os.path.abspath(requested_path)
    return requested_path.startswith(base_path + os.sep)


def validate_backup_filename(filename):
    """Return True when ``filename`` looks like a legitimate backup name."""
    if not filename or not isinstance(filename, str):
        return False
    if not filename.endswith(BACKUP_ARCHIVE_SUFFIX):
        return False
    return not any(token in filename for token in FORBIDDEN_FILENAME_TOKENS)


def safe_extract(tar, path):
    """Extract ``tar`` into ``path``, refusing path traversal attempts."""
    for member in tar.getmembers():
        member_path = os.path.abspath(os.path.join(path, member.name))
        if not is_safe_path(path, member_path):
            raise ValueError(f'Attempted path traversal in tar file: {member.name}')
        tar.extract(member, path)


# ---------------------------------------------------------------------------
# Internal helpers
# ---------------------------------------------------------------------------

def _list_available_backups():
    """Return the backup archive names present in the backup directory."""
    backup_dir = app.config['BACKUP_DIR']
    return [
        filename
        for filename in os.listdir(backup_dir)
        if filename.endswith(BACKUP_ARCHIVE_SUFFIX)
        and is_safe_path(backup_dir, os.path.join(backup_dir, filename))
    ]


def _iter_config_files():
    """Yield ``(arcname, full_path)`` pairs for regular config files."""
    config_dir = app.config['CONFIG_DIR']
    for config_file in os.listdir(config_dir):
        full_path = os.path.join(config_dir, config_file)
        if os.path.isfile(full_path) and is_safe_path(config_dir, full_path):
            yield config_file, full_path


def _write_backup_archive(backup_path):
    """Write every current config file into a gzipped tar archive."""
    with tarfile.open(backup_path, 'w:gz') as tar:
        for config_file, full_path in _iter_config_files():
            tar.add(full_path, arcname=config_file)


def _exceeds_size_limit(path):
    """Return True when the file at ``path`` exceeds the configured limit."""
    return os.path.getsize(path) > app.config['MAX_BACKUP_SIZE']


def _resolve_backup_path(backup_file):
    """Validate ``backup_file`` and return its absolute path on disk."""
    if not validate_backup_filename(backup_file):
        abort(400, MSG_INVALID_BACKUP_FILE)
    backup_path = os.path.join(app.config['BACKUP_DIR'], backup_file)
    if not is_safe_path(app.config['BACKUP_DIR'], backup_path):
        abort(403, MSG_ACCESS_DENIED)
    if not os.path.exists(backup_path):
        abort(404, MSG_BACKUP_NOT_FOUND)
    if not tarfile.is_tarfile(backup_path):
        abort(400, MSG_INVALID_BACKUP_FORMAT)
    return backup_path


def _render_error(message, status_code):
    """Render the shared error template for ``status_code``."""
    return render_template('error.html', error=message), status_code


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------

@app.route(INDEX_ROUTE)
def index():
    backups = []
    try:
        backups = _list_available_backups()
    except Exception as e:
        app.logger.error(f'Error accessing backup directory: {e}')
        flash(MSG_BACKUP_DIR_ERROR)
    return render_template('backup.html', backups=backups)


@app.route(CREATE_BACKUP_ROUTE, methods=['POST'])
def create_backup():
    backup_name = secure_filename(
        request.form.get('backup_name', DEFAULT_BACKUP_NAME)
    ) + BACKUP_ARCHIVE_SUFFIX
    backup_path = os.path.join(app.config['BACKUP_DIR'], backup_name)
    if not is_safe_path(app.config['BACKUP_DIR'], backup_path):
        flash(MSG_INVALID_BACKUP_NAME)
        return redirect(INDEX_ROUTE)
    try:
        _write_backup_archive(backup_path)
        if _exceeds_size_limit(backup_path):
            os.remove(backup_path)
            flash(MSG_BACKUP_TOO_LARGE)
            return redirect(INDEX_ROUTE)
        flash(MSG_BACKUP_CREATED)
    except Exception as e:
        app.logger.error(f'Backup failed: {e}')
        flash(MSG_BACKUP_FAILED)
    return redirect(INDEX_ROUTE)


@app.route(RESTORE_BACKUP_ROUTE)
def restore_config(backup_file):
    try:
        backup_path = _resolve_backup_path(backup_file)
        with tarfile.open(backup_path, 'r:gz') as tar:
            safe_extract(tar, path=app.config['CONFIG_DIR'])
        flash(MSG_RESTORE_SUCCESS)
        return redirect(INDEX_ROUTE)
    except ValueError as e:
        app.logger.error(f'Security violation during restore: {e}')
        abort(400, MSG_INVALID_BACKUP_CONTENTS)
    except Exception as e:
        app.logger.error(f'Restoration failed: {e}')
        abort(500, MSG_RESTORE_FAILED)


# ---------------------------------------------------------------------------
# Error handlers
# ---------------------------------------------------------------------------

@app.errorhandler(404)
def not_found(e):
    return _render_error(MSG_NOT_FOUND, 404)


@app.errorhandler(400)
def bad_request(e):
    return _render_error(MSG_BAD_REQUEST, 400)


@app.errorhandler(403)
def forbidden(e):
    return _render_error(MSG_ACCESS_DENIED, 403)


@app.errorhandler(500)
def server_error(e):
    return _render_error(MSG_SERVER_ERROR, 500)


# ---------------------------------------------------------------------------
# Command-line entry point
# ---------------------------------------------------------------------------

def _ensure_directories():
    """Create the backup and config directories if they are missing."""
    os.makedirs(app.config['BACKUP_DIR'], mode=DIRECTORY_MODE, exist_ok=True)
    os.makedirs(app.config['CONFIG_DIR'], mode=DIRECTORY_MODE, exist_ok=True)


def _write_sample_config(config_path, index):
    """Write a single sample configuration file."""
    with open(config_path, 'w') as f:
        f.write(SAMPLE_CONFIG_CONTENTS_TEMPLATE.format(index=index))


def _create_sample_configs():
    """Populate the config directory with sample configuration files."""
    for i in range(1, SAMPLE_CONFIG_COUNT + 1):
        config_path = os.path.join(
            app.config['CONFIG_DIR'], SAMPLE_CONFIG_NAME_TEMPLATE.format(index=i)
        )
        try:
            _write_sample_config(config_path, i)
