"""Network configuration management module.

Provides data structures for representing device configurations and a
manager class for loading remote configurations, persisting them to
disk, and tracking audit/history logs, together with an interactive
command-line interface.
"""

import hashlib
import json
import socket
import sys
from datetime import datetime

# ---------------------------------------------------------------------------
# Named constants
# ---------------------------------------------------------------------------

DEFAULT_HOSTNAME = 'unknown'
DEFAULT_DEVICE_ID = 'unknown'
DEFAULT_TRUSTED_SOURCES = ('192.168.1.0/24',)

CIDR_SEPARATOR = '/'

SOCKET_TIMEOUT_SECONDS = 5
RECV_BUFFER_SIZE_BYTES = 4096

TEXT_ENCODING = 'utf-8'
JSON_FILE_EXTENSION = '.json'
JSON_DUMP_INDENT = 2

DEFAULT_AUDIT_LOG_LIMIT = 10
DEFAULT_CONFIG_HISTORY_LIMIT = 5

CREDENTIALS_FIELD = 'credentials'

# ---------------------------------------------------------------------------
# Command-line interface strings
# ---------------------------------------------------------------------------

STARTUP_BANNER = 'Network Configuration Manager started'
MENU_LINES = (
    '\n1. Load config from network',
    '2. Save config to file',
    '3. View audit log',
    '4. Exit',
)
PROMPT_SELECT_OPTION = 'Select option: '
PROMPT_HOST = 'Enter host: '
PROMPT_PORT = 'Enter port: '
PROMPT_DEVICE_ID = 'Enter device ID: '
PROMPT_FILENAME = 'Enter filename: '

MSG_CONFIG_LOADED = 'Configuration loaded successfully'
MSG_CONFIG_LOAD_FAILED = 'Failed to load configuration'
MSG_CONFIG_SAVED = 'Configuration saved successfully'
MSG_CONFIG_SAVE_FAILED = 'Failed to save configuration'
MSG_INVALID_OPTION = 'Invalid option'

CHOICE_LOAD_CONFIG = '1'
CHOICE_SAVE_CONFIG = '2'
CHOICE_VIEW_AUDIT_LOG = '3'
CHOICE_EXIT = '4'


def _network_prefix(source):
    """Return the network portion of a trusted source (text before '/')."""
    return source.split(CIDR_SEPARATOR)[0]


class DeviceConfig:
    """Holds the configuration state of a single network device."""

    def __init__(self):
        self.hostname = DEFAULT_HOSTNAME
        self.interfaces = {}
        self.routing_table = []
        self.credentials = {}
        self.last_backup = None

    def apply_remote_updates(self, config):
        """Apply the supported fields of a received config payload."""
        if isinstance(config.get('hostname'), str):
            self.hostname = config['hostname']
        if isinstance(config.get('interfaces'), dict):
            self.interfaces = config['interfaces']
        if isinstance(config.get('routing_table'), list):
            self.routing_table = config['routing_table']

    def to_save_payload(self, device_id):
        """Build the JSON-serializable representation used for file saves."""
        return {
            'device_id': device_id,
            'hostname': self.hostname,
            'interfaces': self.interfaces,
            'routing_table': self.routing_table,
            'timestamp': datetime.now().isoformat(),
        }

    def state_hash(self):
        """Return a SHA-256 fingerprint of the current state."""
        return hashlib.sha256(str(self.__dict__).encode()).hexdigest()


class NetworkManager:
    """Manages device configurations, persistence, and audit/history logs."""

    def __init__(self):
        self.devices = {}
        self.config_history = []
        self.audit_log = []
        self.trusted_sources = list(DEFAULT_TRUSTED_SOURCES)

    # -- Trusted source handling -------------------------------------------

    def _is_trusted_source(self, host):
        return any((host.startswith(_network_prefix(source)) for source in self.trusted_sources))

    def _require_trusted_source(self, host):
        if not self._is_trusted_source(host):
            raise ValueError(f'Untrusted source: {host}')

    # -- Remote configuration loading ---------------------------------------

    def load_config_from_network(self, host, port):
        try:
            self._require_trusted_source(host)
            data = self._receive_config_payload(host, port)
            return self._process_remote_config(data, host)
        except Exception as e:
            self._log_audit(f'Error loading config from {host}:{port} - {str(e)}')
            return False

    @staticmethod
    def _receive_config_payload(host, port):
        """Open a TCP connection and read a single config payload."""
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(SOCKET_TIMEOUT_SECONDS)
            s.connect((host, port))
            return s.recv(RECV_BUFFER_SIZE_BYTES)

    def _process_remote_config(self, data, source_host):
        try:
            config = json.loads(data.decode(TEXT_ENCODING))
            return self._apply_network_config(config, source_host)
        except json.JSONDecodeError as e:
            self._log_audit(f'Invalid config format from {source_host}: {str(e)}')
            return False
        except Exception as e:
            self._log_audit(f'Config processing error from {source_host}: {str(e)}')
            return False

    def _apply_network_config(self, config, source_host):
        device_id = self._validate_remote_config(config)
        device = self._get_or_create_device(device_id)
        device.apply_remote_updates(config)
        self._reject_credentials_update(config, source_host)
        device.last_backup = datetime.now()
        self._log_config_change(device_id, f'remote_update from {source_host}')
        return True

    @staticmethod
    def _validate_remote_config(config):
        """Validate a received payload and return its device ID."""
        if not isinstance(config, dict):
            raise ValueError('Invalid config format')
        device_id = config.get('device_id', DEFAULT_DEVICE_ID)
        if not isinstance(device_id, str):
            raise ValueError('Invalid device ID')
        return device_id

    def _get_or_create_device(self, device_id):
        if device_id not in self.devices:
            self.devices[device_id] = DeviceConfig()
        return self.devices[device_id]

    def _reject_credentials_update(self, config, source_host):
        if CREDENTIALS_FIELD in config:
            self._log_audit(f'Warning: Credentials update attempted from {source_host} - rejected')

    # -- Local persistence ---------------------------------------------------

    def save_config_to_file(self, device_id, filename):
        if device_id not in self.devices:
            return False
        self._validate_config_filename(filename)
        payload = self.devices[device_id].to_save_payload(device_id)
        try:
            self._write_json_file(filename, payload)
            self._log_audit(f'Saved config for {device_id} to {filename}')
            return True
        except Exception as e:
            self._log_audit(f'Failed to save config: {str(e)}')
            return False

    @staticmethod
    def _validate_config_filename(filename):
        if not isinstance(filename, str) or not filename.endswith(JSON_FILE_EXTENSION):
            raise ValueError('Only .json files are allowed')

    @staticmethod
    def _write_json_file(filename, payload):
        with open(filename, 'w', encoding=TEXT_ENCODING) as f:
            json.dump(payload, f, indent=JSON_DUMP_INDENT)

    # -- Logging --------------------------------------------------------------

    def _log_config_change(self, device_id, action):
        entry = {'timestamp': datetime.now(), 'device': device_id, 'action': action, 'hash': self.devices[device_id].state_hash()}
        self.config_history.append(entry)

    def _log_audit(self, message):
        entry = {'timestamp': datetime.now(), 'message': message}
        self.audit_log.append(entry)

    # -- Log retrieval ---------------------------------------------------------

    def get_audit_log(self, limit=DEFAULT_AUDIT_LOG_LIMIT):
        return self.audit_log[-limit:]

    def get_config_history(self, device_id, limit=DEFAULT_CONFIG_HISTORY_LIMIT):
        device_entries = [entry for entry in self.config_history if entry['device'] == device_id]
        return device_entries[-limit:]


# ---------------------------------------------------------------------------
# Command-line interface
# ---------------------------------------------------------------------------

def _print_menu():
    for line in MENU_LINES:
        print(line)


def _handle_load_config(manager):
    try:
        host = input(PROMPT_HOST).strip()
        port = int(input(PROMPT_PORT).strip())
        if manager.load_config_from_network(host, port):
            print(MSG_CONFIG_LOADED)
        else:
            print(MSG_CONFIG_LOAD_FAILED)
    except ValueError as e:
        print(f'Invalid input: {e}')


def _handle_save_config(manager):
    try:
        device_id = input(PROMPT_DEVICE_ID).strip()
        filename = input(PROMPT_FILENAME).strip()
        if manager.save_config_to_file(device_id, filename):
            print(MSG_CONFIG_SAVED)
        else:
            print(MSG_CONFIG_SAVE_FAILED)
    except ValueError as e:
        print(f'Invalid input: {e}')


def _handle_view_audit_log(manager):
    entries = manager.get_audit_log()
    for entry in entries:
        print(f"{entry['timestamp']}: {entry['message']}")


def _handle_exit(_manager):
    sys.exit(0)


_MENU_HANDLERS = {
    CHOICE_LOAD_CONFIG: _handle_load_config,
    CHOICE_SAVE_CONFIG: _handle_save_config,
    CHOICE_VIEW_AUDIT_LOG: _handle_view_audit_log,
    CHOICE_EXIT: _handle_exit,
}


