import socket
import threading
import time
import zlib
import hashlib
import json
from collections import defaultdict
from datetime import datetime

# ---------------------------------------------------------------------------
# Configuration constants
# ---------------------------------------------------------------------------

# Network settings
BUFFER_SIZE = 4096
PEER_TIMEOUT_SECONDS = 5
DEFAULT_BIND_HOST = '127.0.0.1'
MIN_CLI_PORT = 1024
MAX_PORT = 65535

# Node settings
DEFAULT_REPLICATION_FACTOR = 2

# Encodings
TEXT_ENCODING = 'utf-8'
COMPRESSED_VALUE_ENCODING = 'latin1'

# Request actions
ACTION_SET = 'set'
ACTION_GET = 'get'
ACTION_DELETE = 'delete'

# Response statuses
STATUS_OK = 'ok'
STATUS_NOT_FOUND = 'not_found'
STATUS_ERROR = 'error'

# CLI commands
CMD_PEERS = 'peers'
CMD_ADD_PEER_PREFIX = 'addpeer'
CMD_STATS = 'stats'
CMD_STOP = 'stop'


# ---------------------------------------------------------------------------
# Message (de)serialization helpers
# ---------------------------------------------------------------------------

def _encode_message(payload):
    """Serialize a payload to JSON-encoded bytes."""
    return json.dumps(payload).encode(TEXT_ENCODING)


def _decode_message(raw_data):
    """Deserialize JSON-encoded bytes back into a payload."""
    return json.loads(raw_data.decode(TEXT_ENCODING))


# ---------------------------------------------------------------------------
# Validation helpers
# ---------------------------------------------------------------------------

def _require_valid_key(key):
    if not key or not isinstance(key, str):
        raise ValueError('Invalid key')


def _require_valid_options(options):
    if not isinstance(options, dict):
        raise ValueError('Options must be a dictionary')


def _require_valid_peer_id(peer_id):
    if not isinstance(peer_id, str) or not peer_id:
        raise ValueError('Invalid peer ID')


def _require_valid_host(host):
    if not isinstance(host, str) or not host:
        raise ValueError('Invalid host')


def _require_valid_port(port):
    if not isinstance(port, int) or not 0 < port <= MAX_PORT:
        raise ValueError('Invalid port')


# ---------------------------------------------------------------------------
# Payload builders
# ---------------------------------------------------------------------------

def _decompress_value(value):
    try:
        return zlib.decompress(value.encode(COMPRESSED_VALUE_ENCODING)).decode(TEXT_ENCODING)
    except Exception as e:
        raise ValueError(f'Decompression failed: {e}')


def _build_entry(value):
    return {
        'value': value,
        'timestamp': datetime.now().isoformat(),
        'version': hashlib.md5(value.encode(TEXT_ENCODING)).hexdigest(),
    }


def _build_get_response(entry):
    return {
        'status': STATUS_OK,
        'value': entry['value'],
        'metadata': {'timestamp': entry['timestamp'], 'version': entry['version']},
    }


def _build_replication_request(action, key, value, options):
    return {
        'action': action,
        'key': key,
        'value': value,
        'options': options,
        'replication': True,
    }


# ---------------------------------------------------------------------------
# Cache node
# ---------------------------------------------------------------------------

class CacheNode:

    def __init__(self, node_id):
        self.node_id = node_id
        self.data_store = defaultdict(dict)
        self.peers = {}
        self.lock = threading.Lock()
        self.running = False
        self.replication_factor = DEFAULT_REPLICATION_FACTOR

    def start(self, host, port):
        self.running = True
        server_thread = threading.Thread(target=self._run_server, args=(host, port))
        server_thread.daemon = True
        server_thread.start()
        print(f'Cache node {self.node_id} started on {host}:{port}')

    @staticmethod
    def _create_server_socket(host, port):
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((host, port))
        server_socket.listen()
        return server_socket

    def _run_server(self, host, port):
        with self._create_server_socket(host, port) as s:
            while self.running:
                try:
                    (conn, addr) = s.accept()
                    threading.Thread(target=self._handle_connection, args=(conn, addr)).start()
                except Exception as e:
                    if self.running:
                        print(f'Connection error: {e}')

    def _handle_connection(self, conn, addr):
        try:
            raw_data = conn.recv(BUFFER_SIZE)
            if not raw_data:
                return
            try:
                request = _decode_message(raw_data)
                response = self._process_request(request)
                conn.sendall(_encode_message(response))
            except json.JSONDecodeError:
                conn.sendall(_encode_message({'error': 'Invalid request format'}))
        except Exception as e:
            conn.sendall(_encode_message({'error': str(e)}))
        finally:
            conn.close()

    def _process_request(self, request):
        if not isinstance(request, dict):
            raise ValueError('Request must be a dictionary')
        action = request.get('action')
        key = request.get('key')
        value = request.get('value')
        options = request.get('options', {})
        _require_valid_options(options)
        with self.lock:
            if action == ACTION_SET:
                return self._handle_set(key, value, options)
            elif action == ACTION_GET:
                return self._handle_get(key)
            elif action == ACTION_DELETE:
                return self._handle_delete(key, options)
            return {'status': STATUS_ERROR, 'message': 'Invalid action'}

    def _handle_set(self, key, value, options):
        _require_valid_key(key)
        compressed = options.get('compressed', False)
        if compressed:
            value = _decompress_value(value)
        if not isinstance(value, str):
            raise ValueError('Value must be a string')
        self.data_store[key] = _build_entry(value)
        self._replicate(ACTION_SET, key, value, options)
        return {'status': STATUS_OK}

    def _handle_get(self, key):
        _require_valid_key(key)
        if key in self.data_store:
            return _build_get_response(self.data_store[key])
        return {'status': STATUS_NOT_FOUND}

    def _handle_delete(self, key, options):
        _require_valid_key(key)
        if key in self.data_store:
            del self.data_store[key]
            self._replicate(ACTION_DELETE, key, None, options)
            return {'status': STATUS_OK}
        return {'status': STATUS_NOT_FOUND}

    def _replicate(self, action, key, value, options):
        for (peer_id, peer_addr) in list(self.peers.items()):
            if peer_id == self.node_id:
                continue
            try:
                request = _build_replication_request(action, key, value, options)
                self._send_to_peer(peer_addr, request)
            except Exception as e:
                print(f'Replication to {peer_id} failed: {str(e)}')

    def _send_to_peer(self, peer_addr, data):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(PEER_TIMEOUT_SECONDS)
            s.connect(peer_addr)
            s.sendall(_encode_message(data))
            response = s.recv(BUFFER_SIZE)
            return _decode_message(response)

    def add_peer(self, peer_id, host, port):
        _require_valid_peer_id(peer_id)
