"""A simple distributed cache node with peer-to-peer replication and a CLI.

Each node serves JSON requests over TCP for ``set``/``get``/``delete``
operations and replicates mutations to its registered peers on a
best-effort basis.
"""

import hashlib
import json
import socket
import threading
import time
import zlib
from collections import defaultdict
from datetime import datetime

# Network settings.
BUFFER_SIZE = 4096
PEER_TIMEOUT_SECONDS = 5

# Port validation bounds.
MAX_PORT = 65535
MIN_CLI_PORT = 1024

# CLI defaults.
DEFAULT_HOST = '127.0.0.1'


class CacheNode:
    """A cache node that stores key/value pairs and replicates to peers."""

    def __init__(self, node_id):
        self.node_id = node_id
        self.data_store = defaultdict(dict)
        self.peers = {}
        self.lock = threading.Lock()
        self.running = False
        self.replication_factor = 2

    def start(self, host, port):
        """Start the node's server loop on a background daemon thread."""
        self.running = True
        server_thread = threading.Thread(target=self._run_server, args=(host, port))
        server_thread.daemon = True
        server_thread.start()
        print(f'Cache node {self.node_id} started on {host}:{port}')

    def _run_server(self, host, port):
        """Accept incoming connections until the node is stopped."""
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server_socket:
            server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            server_socket.bind((host, port))
            server_socket.listen()
            while self.running:
                try:
                    conn, addr = server_socket.accept()
                    threading.Thread(target=self._handle_connection, args=(conn, addr)).start()
                except Exception as e:
                    if self.running:
                        print(f'Connection error: {e}')

    def _handle_connection(self, conn, addr):
        """Process a single request/response exchange, then close the socket."""
        try:
            raw_data = conn.recv(BUFFER_SIZE)
            if not raw_data:
                return
            try:
                request = json.loads(raw_data.decode('utf-8'))
                response = self._process_request(request)
                self._send_response(conn, response)
            except json.JSONDecodeError:
                self._send_response(conn, {'error': 'Invalid request format'})
        except Exception as e:
            self._send_response(conn, {'error': str(e)})
        finally:
            conn.close()

    @staticmethod
    def _send_response(conn, response):
        """Serialize and send a response dictionary to the client."""
        conn.sendall(json.dumps(response).encode('utf-8'))

    def _process_request(self, request):
        """Validate and dispatch a request, returning the response dict."""
        if not isinstance(request, dict):
            raise ValueError('Request must be a dictionary')
        action = request.get('action')
        key = request.get('key')
        value = request.get('value')
        options = request.get('options', {})
        if not isinstance(options, dict):
            raise ValueError('Options must be a dictionary')
        with self.lock:
            if action == 'set':
                return self._handle_set(key, value, options)
            if action == 'get':
                return self._handle_get(key)
            if action == 'delete':
                return self._handle_delete(key, options)
            return {'status': 'error', 'message': 'Invalid action'}

    def _handle_set(self, key, value, options):
        """Store a value for a key and replicate the operation."""
        self._validate_key(key)
        if options.get('compressed', False):
            value = self._decompress_value(value)
        if not isinstance(value, str):
            raise ValueError('Value must be a string')
        self.data_store[key] = self._build_entry(value)
        self._replicate('set', key, value, options)
        return {'status': 'ok'}

    def _handle_get(self, key):
        """Return the stored value and metadata for a key, if present."""
        self._validate_key(key)
        if key in self.data_store:
            entry = self.data_store[key]
            return {
                'status': 'ok',
                'value': entry['value'],
                'metadata': {
                    'timestamp': entry['timestamp'],
                    'version': entry['version'],
                },
            }
        return {'status': 'not_found'}

    def _handle_delete(self, key, options):
        """Remove a key and replicate the deletion, if the key exists."""
        self._validate_key(key)
        if key in self.data_store:
            del self.data_store[key]
            self._replicate('delete', key, None, options)
            return {'status': 'ok'}
        return {'status': 'not_found'}

    @staticmethod
    def _validate_key(key):
        """Ensure a key is a non-empty string."""
        if not key or not isinstance(key, str):
            raise ValueError('Invalid key')

    @staticmethod
    def _decompress_value(value):
        """Decode a latin1-encoded zlib payload back into a UTF-8 string."""
        try:
            return zlib.decompress(value.encode('latin1')).decode('utf-8')
        except Exception as e:
            raise ValueError(f'Decompression failed: {e}')

    @staticmethod
    def _build_entry(value):
        """Create a store entry with value, timestamp and version hash."""
        return {
            'value': value,
            'timestamp': datetime.now().isoformat(),
            'version': hashlib.md5(value.encode('utf-8')).hexdigest(),
        }

    def _replicate(self, action, key, value, options):
        """Best-effort replication of an operation to every known peer."""
        for peer_id, peer_addr in list(self.peers.items()):
            if peer_id == self.node_id:
                continue
            try:
                request = {
                    'action': action,
                    'key': key,
                    'value': value,
                    'options': options,
                    'replication': True,
                }
                self._send_to_peer(peer_addr, request)
            except Exception as e:
                print(f'Replication to {peer_id} failed: {str(e)}')

    def _send_to_peer(self, peer_addr, data):
        """Send a request to a peer and return its decoded response."""
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as peer_socket:
            peer_socket.settimeout(PEER_TIMEOUT_SECONDS)
            peer_socket.connect(peer_addr)
            peer_socket.sendall(json.dumps(data).encode('utf-8'))
            response = peer_socket.recv(BUFFER_SIZE)
            return json.loads(response.decode('utf-8'))

    def add_peer(self, peer_id, host, port):
        """Register a peer after validating its ID and address."""
        if not isinstance(peer_id, str) or not peer_id:
            raise ValueError('Invalid peer ID')
        if not isinstance(host, str) or not host:
            raise ValueError('Invalid host')
        if not isinstance(port, int) or not 0 < port <= MAX_PORT:
            raise ValueError('Invalid port')
        self.peers[peer_id] = (host, port)

    def stop(self):
        """Stop the node so the server loop exits."""
        self.running = False

    def get_stats(self):
        """Return a snapshot of the node's current statistics."""
        with self.lock:
            return {
                'node_id': self.node_id,
                'item_count': len(self.data_store),
                'peer_count': len(self.peers),
                'status': 'running' if self.running else 'stopped',
            }


def _handle_addpeer(node, cmd):
    """Handle the ``addpeer <id> <host> <port>`` command."""
    try:
        _, peer_id, peer_host, peer_port = cmd.split()
        node.add_peer(peer_id, peer_host, int(peer_port))
        print(f'Added peer {peer_id} at {peer_host}:{peer_port}')
    except ValueError as e:
        print(f'Error: {e}')


def _handle_command(node, cmd):
    """Execute a single CLI command.

    Returns True to keep the command loop running, False to exit it.
    """
    if cmd == 'peers':
        print('Connected peers:', node.peers)
    elif cmd.startswith('addpeer'):
        _handle_addpeer(node, cmd)
    elif cmd == 'stats':
        print(node.get_stats())
    elif cmd == 'stop':
        node.stop()
        return False
    else:
        print('Unknown command')
    return True


def main():
    """Interactive entry point: configure and run a cache node."""
    node_id = input('Enter node ID: ').strip()
    if not node_id:
        print('Error: Node ID cannot be empty')
        return
    host = input('Enter host to bind to [127.0.0.1]: ').strip() or DEFAULT_HOST
    try:
        port = int(input('Enter port: ').strip())
        if not MIN_CLI_PORT <= port <= MAX_PORT:
            raise ValueError('Port must be between 1024 and 65535')
    except ValueError as e:
        print(f'Error: {e}')
        return
    node = CacheNode

