TRANSFORM_UPPERCASE = 'uppercase'
TRANSFORM_LOWERCASE = 'lowercase'

CONFIG_KEY_SETTINGS = 'settings'
CONFIG_KEY_TRANSFORM = 'transform'

# Builtins exposed to sandboxed Python plugins.
SANDBOXED_BUILTINS: Dict[str, Any] = {
    'str': str,
    'int': int,
    'float': float,
    'bool': bool,
    'list': list,
    'dict': dict,
    'tuple': tuple,
    'range': range,
    'len': len,
    'sum': sum,
    'min': min,
    'max': max,
    'abs': abs,
    'round': round,
}

# CLI option identifiers.
MENU_OPTION_LOAD_PLUGIN = '1'
MENU_OPTION_CREATE_DOCUMENT = '2'
MENU_OPTION_PROCESS_DOCUMENT = '3'
MENU_OPTION_EXIT = '4'

# CLI messages.
MSG_UNSUPPORTED_PLUGIN_FORMAT = 'Unsupported plugin format: {}'
MSG_PLUGIN_LOAD_FAILED = 'Failed to load plugin {}: {}'
MSG_PROCESSING_FAILED = 'Processing failed: {}'

ERROR_EMPTY_PATH = 'Error: Path cannot be empty'
ERROR_EMPTY_CONTENT = 'Error: Content cannot be empty'
ERROR_MISSING_PROCESS_ARGUMENTS = 'Error: Document ID and plugin name are required'
ERROR_INVALID_OPTION = 'Invalid option'


# ---------------------------------------------------------------------------
# Helper functions
# ---------------------------------------------------------------------------

def _compute_content_checksum(content: str) -> str:
    """Return the checksum used to fingerprint document content."""
    return hashlib.md5(content.encode()).hexdigest()


def _compute_document_id(content: str) -> str:
    """Return the identifier used to look up a document by its content."""
    return hashlib.sha256(content.encode()).hexdigest()


def _build_initial_metadata(content: str) -> Dict[str, Any]:
    """Build the metadata mapping assigned to every new document."""
    return {
        'created': datetime.now(),
        'modified': datetime.now(),
        'checksum': _compute_content_checksum(content),
    }


def _build_plugin_record(plugin_type: str, plugin_path: str) -> Dict[str, Any]:
    """Build the bookkeeping record kept for every loaded plugin."""
    return {'type': plugin_type, 'path': plugin_path, 'loaded_at': datetime.now()}


def _build_error_annotation(plugin_name: str, message: str) -> Dict[str, Any]:
    """Build the annotation attached to a document when processing fails."""
    return {
        'type': ANNOTATION_TYPE_ERROR,
        'plugin': plugin_name,
        'message': message,
        'timestamp': datetime.now(),
    }


def _find_plugin_class(module: Any) -> Optional[type]:
    """Return the first class flagged as a plugin in *module*, if any."""
    for (name, obj) in inspect.getmembers(module):
        if inspect.isclass(obj) and hasattr(obj, 'is_plugin') and obj.is_plugin:
            return obj
    return None


def _read_json_file(file_path: str) -> Any:
    """Read and parse a JSON file, normalising parse errors to ValueError."""
    with open(file_path, 'r', encoding='utf-8') as f:
        try:
            return json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f'Invalid JSON format: {str(e)}')


def _extract_plugin_name(plugin_data: Any) -> str:
    """Validate and return the plugin name stored in the plugin payload."""
    plugin_name = plugin_data.get('name')
    if not plugin_name or not isinstance(plugin_name, str):
        raise ValueError('Plugin name must be a non-empty string')
    return plugin_name


def _build_plugin_config(plugin_data: Any, plugin_name: str) -> Dict[str, Any]:
    """Keep only the whitelisted configuration fields of a JSON plugin."""
    return {
        'name': plugin_name,
        'version': plugin_data.get('version', DEFAULT_PLUGIN_VERSION),
        'description': plugin_data.get('description', ''),
        'settings': plugin_data.get('settings', {}),
    }


def _apply_configured_transform(content: str, settings: Dict[str, Any]) -> str:
    """Apply the transform declared in the plugin settings, if present."""
    result = content
    if CONFIG_KEY_TRANSFORM in settings:
        transform = settings[CONFIG_KEY_TRANSFORM]
        if transform == TRANSFORM_UPPERCASE:
            result = result.upper()
        elif transform == TRANSFORM_LOWERCASE:
            result = result.lower()
    return result


def _make_json_plugin_class(allowed_config: Dict[str, Any]) -> type:
    """Create a plugin class bound to the given whitelisted configuration."""

    class JsonPlugin:
        is_plugin = True

        def __init__(self):
            self.config = allowed_config

        def process(self, document):
            return _apply_configured_transform(document.content, self.config[CONFIG_KEY_SETTINGS])

    return JsonPlugin


# ---------------------------------------------------------------------------
# Core classes
# ---------------------------------------------------------------------------

class Document:

    def __init__(self, content: str):
        self.content = content
        self.metadata = _build_initial_metadata(content)
        self.annotations = []
        self.processed_content = None

    def _mark_processed(self, plugin_name: str) -> None:
        self.metadata['modified'] = datetime.now()
        self.metadata['processed_by'] = plugin_name

    def _record_error(self, plugin_name: str, message: str) -> None:
        self.annotations.append(_build_error_annotation(plugin_name, message))


class PluginManager:

    def __init__(self):
        self.plugins = {}
        self.loaded_plugins = {}
        self.document_cache = {}
        self.plugin_data_dir = DEFAULT_PLUGIN_DATA_DIR
        os.makedirs(self.plugin_data_dir, exist_ok=True)

    def load_plugin(self, plugin_path: str) -> bool:
        try:
            if not os.path.exists(plugin_path):
                raise ValueError('Plugin file does not exist')
            loader = self._resolve_loader(plugin_path)
            if loader is None:
                print(MSG_UNSUPPORTED_PLUGIN_FORMAT.format(plugin_path))
                return False
            return loader(plugin_path)
        except Exception as e:
            print(MSG_PLUGIN_LOAD_FAILED.format(plugin_path, str(e)))
            return False

    def _resolve_loader(self, plugin_path: str) -> Optional[Callable[[str], bool]]:
        if plugin_path.endswith(PYTHON_PLUGIN_EXTENSION):
            return self._load_python_plugin
        if plugin_path.endswith(JSON_PLUGIN_EXTENSION):
            return self._load_json_plugin
        return None

    def _register_plugin(self, plugin_name: str, plugin_class: type, plugin_type: str, plugin_path: str) -> None:
        self.plugins[plugin_name] = plugin_class
        self.loaded_plugins[plugin_name] = _build_plugin_record(plugin_type, plugin_path)

    def _data_file_path(self, plugin_name: str) -> str:
        return os.path.join(self.plugin_data_dir, f'{plugin_name}.json')

    def _write_plugin_data(self, plugin_name: str, data: Dict[str, Any]) -> None:
        with open(self._data_file_path(plugin_name), 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2)

    def _load_python_plugin(self, plugin_path: str) -> bool:
        plugin_name = os.path.splitext(os.path.basename(plugin_path))[0]
        module = self._load_sandboxed_module(plugin_name, plugin_path)
        plugin_class = _find_plugin_class(module)
        if plugin_class is None:
            return False
        self._register_plugin(plugin_name, plugin_class, PLUGIN_TYPE_PYTHON, plugin_path)
        return True

    @staticmethod
    def _load_sandboxed_module(plugin_name: str, plugin_path: str) -> Any:
        spec = importlib.util.spec_from_file_location(plugin_name, plugin_path)
        module = importlib.util.module_from_spec(spec)
        module.__dict__['__builtins__'] = dict(SANDBOXED_BUILTINS)
        spec.loader.exec_module(module)
        return module

    def _load_json_plugin(self, plugin_path: str) -> bool:
        plugin_data = _read_json_file(plugin_path)
        plugin_name = _extract_plugin_name(plugin_data)
        allowed_config = _build_plugin_config(plugin_data, plugin_name)
        self._write_plugin_data(plugin_name, allowed_config)
        plugin_class = _make_json_plugin_class(allowed_config)
        self._register_plugin(plugin_name, plugin_class, PLUGIN_TYPE_JSON, plugin_path)
        return True

    def process_document(self, plugin_name: str, document: Document) -> Document:
        if plugin_name not in self.plugins:
            raise ValueError(f'Plugin {plugin_name} not loaded')
        plugin_instance = self.plugins[plugin_name]()
