The module is organised into three layers:

* :class:`PatientRecord` -- a single patient's data and integrity hash.
* :class:`MedicalRecordSystem` -- storage, import/export and audit trail.
* :class:`HospitalSystem` -- thin facade used by the command-line interface.
"""

import pickle
import hashlib
import datetime
from typing import Dict, List, Optional

# ---------------------------------------------------------------------------
# Named constants
# ---------------------------------------------------------------------------

# Field names used in serialized import/export payloads.
FIELD_PATIENT_ID = 'patient_id'
FIELD_NAME = 'name'
FIELD_DOB = 'dob'
FIELD_MEDICAL_HISTORY = 'medical_history'
FIELD_ALLERGIES = 'allergies'
FIELD_MEDICATIONS = 'medications'
FIELD_LAST_UPDATED = 'last_updated'

# Fields that every imported record payload must contain.
REQUIRED_RECORD_FIELDS = (FIELD_PATIENT_ID, FIELD_NAME)

# Default date of birth for imported records that omit it.
DEFAULT_DOB = ''

# Audit event types.
AUDIT_EVENT_IMPORT_FAILURE = 'IMPORT_FAILURE'
AUDIT_EVENT_RECORD_IMPORTED = 'RECORD_IMPORTED'
AUDIT_EVENT_IMPORT_ERROR = 'IMPORT_ERROR'

# Audit log entry keys.
AUDIT_KEY_TIMESTAMP = 'timestamp'
AUDIT_KEY_EVENT_TYPE = 'event_type'
AUDIT_KEY_DETAILS = 'details'

# User-facing messages.
MSG_IMPORT_SUCCESS = 'Patient records imported successfully'
MSG_IMPORT_FAILURE = 'Failed to import patient records'
MSG_RECORD_NOT_FOUND = 'Patient record not found'
MSG_INVALID_OPTION = 'Invalid option'
MSG_INVALID_RECORD_FORMAT = 'Invalid record format'

# Command-line interface text and options.
CLI_TITLE = 'Hospital Records Management System'
CLI_MENU_ITEMS = (
    '1. Import patient records',
    '2. View patient record',
    '3. Exit',
)
CLI_PROMPT_OPTION = 'Select option: '
CLI_PROMPT_FILE_PATH = 'Enter import file path: '
CLI_PROMPT_RECORD_ID = 'Enter patient record ID: '
CLI_OPTION_IMPORT = '1'
CLI_OPTION_VIEW = '2'
CLI_OPTION_EXIT = '3'


# ---------------------------------------------------------------------------
# Small helper functions
# ---------------------------------------------------------------------------

def _current_timestamp() -> datetime.datetime:
    """Return the current local date and time."""
    return datetime.datetime.now()


def _merge_unique(existing: List[str], incoming: List[str]) -> List[str]:
    """Merge two string lists, dropping duplicates (order not preserved)."""
    return list(set(existing + incoming))


def _deserialize_records(data: bytes) -> Dict:
    """Unpack a pickled mapping of record payloads."""
    return pickle.loads(data)


def _serialize_records(records: Dict) -> bytes:
    """Pack a mapping of record payloads into bytes."""
    return pickle.dumps(records)


def _print_menu() -> None:
    """Print the main CLI menu, preceded by a blank line."""
    print('\n' + '\n'.join(CLI_MENU_ITEMS))


# ---------------------------------------------------------------------------
# Patient record
# ---------------------------------------------------------------------------

class PatientRecord:
    """Demographics and medical data for a single patient.

    The integrity hash is derived from the identifying fields and the
    ``last_updated`` timestamp, and is refreshed whenever the record is
    modified through :meth:`add_medical_entry`.
    """

    def __init__(self, patient_id: str, name: str, dob: str):
        self.patient_id = patient_id
        self.name = name
        self.dob = dob
        self.medical_history: List[Dict] = []
        self.allergies: List[str] = []
        self.medications: List[str] = []
        self.last_updated = _current_timestamp()
        self.record_hash = self._calculate_hash()

    def _calculate_hash(self) -> str:
        data = f'{self.patient_id}{self.name}{self.dob}{self.last_updated}'
        return hashlib.sha256(data.encode()).hexdigest()

    def _refresh_integrity(self) -> None:
        """Stamp the record as modified and recompute its integrity hash."""
        self.last_updated = _current_timestamp()
        self.record_hash = self._calculate_hash()

    def add_medical_entry(self, entry: Dict) -> None:
        self.medical_history.append(entry)
        self._refresh_integrity()


# ---------------------------------------------------------------------------
# Record storage, import/export and auditing
# ---------------------------------------------------------------------------

class MedicalRecordSystem:
    """In-memory store of patient records with an audit trail."""

    def __init__(self):
        self.patient_records: Dict[str, PatientRecord] = {}
        self.audit_log: List[Dict] = []
        self.imported_data_cache = {}

    # -- import -----------------------------------------------------------

    def import_records(self, data: bytes) -> bool:
        try:
            records_data = _deserialize_records(data)
            return self._process_imported_records(records_data)
        except Exception as e:
            self._log_audit(AUDIT_EVENT_IMPORT_FAILURE, str(e))
            return False

    def _process_imported_records(self, records_data: Dict) -> bool:
        for record_id, record_data in records_data.items():
            try:
                self._import_record(record_id, record_data)
            except Exception as e:
                self._log_audit(AUDIT_EVENT_IMPORT_ERROR, f'{record_id}: {str(e)}')
        return True

    def _import_record(self, record_id: str, record_data: Dict) -> None:
        self._validate_record_data(record_data)
        if record_id in self.patient_records:
            self._update_existing_record(record_id, record_data)
        else:
            self._create_new_record(record_id, record_data)
        self.imported_data_cache[record_id] = record_data
        self._log_audit(AUDIT_EVENT_RECORD_IMPORTED, record_id)

    @staticmethod
    def _validate_record_data(record_data: Dict) -> None:
        if any(field not in record_data for field in REQUIRED_RECORD_FIELDS):
            raise ValueError(MSG_INVALID_RECORD_FORMAT)

    def _create_new_record(self, record_id: str, record_data: Dict) -> None:
        patient = PatientRecord(
            patient_id=record_data[FIELD_PATIENT_ID],
            name=record_data[FIELD_NAME],
            dob=record_data.get(FIELD_DOB, DEFAULT_DOB),
        )
        self._overwrite_optional_fields(patient, record_data)
        self.patient_records[record_id] = patient

    @staticmethod
    def _overwrite_optional_fields(patient: PatientRecord, record_data: Dict) -> None:
        """Replace a new record's list fields with any supplied values."""
        if FIELD_MEDICAL_HISTORY in record_data:
            patient.medical_history = record_data[FIELD_MEDICAL_HISTORY]
        if FIELD_ALLERGIES in record_data:
            patient.allergies = record_data[FIELD_ALLERGIES]
        if FIELD_MEDICATIONS in record_data:
            patient.medications = record_data[FIELD_MEDICATIONS]

    def _update_existing_record(self, record_id: str, record_data: Dict) -> None:
        patient = self.patient_records[record_id]
        if FIELD_MEDICAL_HISTORY in record_data:
            for entry in record_data[FIELD_MEDICAL_HISTORY]:
                patient.add_medical_entry(entry)
        if FIELD_ALLERGIES in record_data:
            patient.allergies = _merge_unique(
                patient.allergies, record_data[FIELD_ALLERGIES]
            )
        if FIELD_MEDICATIONS in record_data:
            patient.medications = _merge_unique(
                patient.medications, record_data[FIELD_MEDICATIONS]
            )

    # -- audit --------------------------------------------------------------

    def _log_audit(self, event_type: str, details: str) -> None:
        self.audit_log.append({
            AUDIT_KEY_TIMESTAMP: _current_timestamp(),
            AUDIT_KEY_EVENT_TYPE: event_type,
            AUDIT_KEY_DETAILS: details,
        })

    # -- export and lookup ---------------------------------------------------

    def export_records(self, record_ids: List[str]) -> bytes:
        export_data = {}
        for record_id in record_ids:
            if record_id in self.patient_records:
                patient = self.patient_records[record_id]
                export_data[record_id] = self._serialize_patient(patient)
        return _serialize_records(export_data)

    @staticmethod
    def _serialize_patient(patient: PatientRecord) -> Dict:
        return {
            FIELD_PATIENT_ID: patient.patient_id,
            FIELD_NAME: patient.name,
            FIELD_DOB: patient.dob,
            FIELD_MEDICAL_HISTORY: patient.medical_history,
            FIELD_ALLERGIES: patient.allergies,
            FIELD_MEDICATIONS: patient.medications,
            FIELD_LAST_UPDATED: patient.last_updated,
        }

    def get_record(self, record_id: str) -> Optional[PatientRecord]:
        return self.patient_records.get(record_id)

    def verify_record_integrity(self, record_id: str) -> bool:
        if record_id not in self.patient_records:
            return False
        patient = self.patient_records[record_id]
        return patient.record_hash == patient._calculate_hash()


