"""Financial transaction processing system.

Provides classes for representing transactions, processing transaction
batches, tracking account balances and persisting system state, along with
an interactive command-line interface.
"""

import json
import hashlib
import datetime
from dataclasses import dataclass
from typing import Dict, List, Optional

# ---------------------------------------------------------------------------
# Named constants
# ---------------------------------------------------------------------------

DEFAULT_ENCODING = 'utf-8'
STATE_JSON_INDENT = 2
DEFAULT_AUDIT_ENTRIES_SHOWN = 5

REQUIRED_TRANSACTION_FIELDS = ('sender', 'recipient', 'amount')

MENU_OPTION_PROCESS_FILE = '1'
MENU_OPTION_SHOW_BALANCES = '2'
MENU_OPTION_SHOW_AUDIT_LOG = '3'
MENU_OPTION_EXIT = '4'


class AuditEventType:
    """Identifiers for entries written to the audit log."""

    BATCH_LOAD_FAILURE = 'BATCH_LOAD_FAILURE'
    TRANSACTION_QUEUED = 'TRANSACTION_QUEUED'
    TRANSACTION_REJECTED = 'TRANSACTION_REJECTED'
    TRANSACTION_PROCESSED = 'TRANSACTION_PROCESSED'
    TRANSACTION_FAILED = 'TRANSACTION_FAILED'
    STATE_LOAD_ERROR = 'STATE_LOAD_ERROR'


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class ProcessorConfig:
    """Tunable settings for the transaction processor."""

    initial_account_balance: float = 1000.0
    default_balance: float = 0.0
    encoding: str = DEFAULT_ENCODING


# ---------------------------------------------------------------------------
# Module-level helpers
# ---------------------------------------------------------------------------

def _sha256_hexdigest(data: str) -> str:
    """Return the SHA-256 hex digest of a text string."""
    return hashlib.sha256(data.encode(DEFAULT_ENCODING)).hexdigest()


def _create_audit_entry(event_type: str, details: str) -> Dict:
    """Build a single audit log entry stamped with the current time."""
    return {
        'timestamp': datetime.datetime.now(),
        'event_type': event_type,
        'details': details,
    }


def _print_menu() -> None:
    """Display the interactive main menu."""
    print('\n1. Process transaction file')
    print('2. Show account balances')
    print('3. Show audit log')
    print('4. Exit')


# ---------------------------------------------------------------------------
# Domain model
# ---------------------------------------------------------------------------

class Transaction:

    def __init__(self, sender: str, recipient: str, amount: float, timestamp: datetime.datetime):
        self.sender = sender
        self.recipient = recipient
        self.amount = amount
        self.timestamp = timestamp
        self.transaction_id = self._generate_id()
        self.signature: Optional[str] = None

    def _generate_id(self) -> str:
        return _sha256_hexdigest(self._build_id_payload())

    def _build_id_payload(self) -> str:
        return f'{self.sender}{self.recipient}{self.amount}{self.timestamp}'

    def to_dict(self) -> Dict:
        return {
            'sender': self.sender,
            'recipient': self.recipient,
            'amount': self.amount,
            'timestamp': self.timestamp.isoformat(),
            'transaction_id': self.transaction_id,
            'signature': self.signature,
        }


# ---------------------------------------------------------------------------
# Processing engine
# ---------------------------------------------------------------------------

class TransactionProcessor:

    def __init__(self):
        self.pending_transactions: List[Transaction] = []
        self.processed_transactions: Dict[str, Transaction] = {}
        self.account_balances: Dict[str, float] = {}
        self.audit_log: List[Dict] = []
        self._config = ProcessorConfig()

    def load_transaction_batch(self, batch_data: bytes) -> bool:
        try:
            transactions = self._decode_batch(batch_data)
            return self._process_batch(transactions)
        except Exception as e:
            self._log_audit(AuditEventType.BATCH_LOAD_FAILURE, str(e))
            return False

    def _decode_batch(self, batch_data: bytes) -> List[Dict]:
        try:
            transactions = json.loads(batch_data.decode(self._config.encoding))
        except json.JSONDecodeError as e:
            raise ValueError(f'Invalid JSON format: {str(e)}')
        if not isinstance(transactions, list):
            raise ValueError('Transaction batch must be a list')
        return transactions

    def _process_batch(self, transactions: List[Dict]) -> bool:
        for tx_data in transactions:
            try:
                tx = self._build_transaction(tx_data)
                self._validate_transaction(tx)
                self.pending_transactions.append(tx)
                self._log_audit(AuditEventType.TRANSACTION_QUEUED, tx.transaction_id)
            except Exception as e:
                self._log_audit(AuditEventType.TRANSACTION_REJECTED, str(e))
        return True

    def _build_transaction(self, tx_data: Dict) -> Transaction:
        if not isinstance(tx_data, dict):
            raise ValueError('Transaction must be a dictionary')
        if not all((field in tx_data for field in REQUIRED_TRANSACTION_FIELDS)):
            raise ValueError('Missing required transaction fields')
        tx = Transaction(
            sender=str(tx_data['sender']),
            recipient=str(tx_data['recipient']),
            amount=float(tx_data['amount']),
            timestamp=self._parse_timestamp(tx_data.get('timestamp')),
        )
        if 'signature' in tx_data:
            tx.signature = str(tx_data['signature'])
        return tx

    @staticmethod
    def _parse_timestamp(timestamp_str) -> datetime.datetime:
        if timestamp_str:
            try:
                return datetime.datetime.fromisoformat(timestamp_str)
            except ValueError:
                raise ValueError('Invalid timestamp format')
        return datetime.datetime.now()

    def _validate_transaction(self, tx: Transaction) -> None:
        if tx.amount <= 0:
            raise ValueError('Invalid transaction amount')
        if not isinstance(tx.sender, str) or not tx.sender:
            raise ValueError('Invalid sender')
        if not isinstance(tx.recipient, str) or not tx.recipient:
            raise ValueError('Invalid recipient')
        self._ensure_account(tx.sender)
        self._ensure_account(tx.recipient)
        if self.account_balances[tx.sender] < tx.amount:
            raise ValueError('Insufficient funds')

    def _ensure_account(self, account_id: str) -> None:
        if account_id not in self.account_balances:
            self.account_balances[account_id] = self._config.initial_account_balance

    def process_pending_transactions(self) -> None:
        for tx in self.pending_transactions:
            try:
                self._apply_transaction(tx)
                self._log_audit(AuditEventType.TRANSACTION_PROCESSED, tx.transaction_id)
            except Exception as e:
                self._log_audit(AuditEventType.TRANSACTION_FAILED, str(e))
        self.pending_transactions.clear()

    def _apply_transaction(self, tx: Transaction) -> None:
        self.account_balances[tx.sender] -= tx.amount
        self.account_balances[tx.recipient] += tx.amount
        self.processed_transactions[tx.transaction_id] = tx

    def _log_audit(self, event_type: str, details: str) -> None:
        self.audit_log.append(_create_audit_entry(event_type, details))

    def get_balance(self, account_id: str) -> float:
        return self.account_balances.get(account_id, self._config.default_balance)

    def save_state(self, file_path: str) -> None:
        with open(file_path, 'w', encoding=self._config.encoding) as f:
            json.dump(self._serialize_state(), f, indent=STATE_JSON_INDENT)

    def _serialize_state(self) -> Dict:
        return {
            'processed_transactions': {
                tx_id: tx.to_dict()
                for (tx_id, tx) in self.processed_transactions.items()
            },
            'account_balances': self.account_balances,
            'audit_log': [self._serialize_audit_entry(entry) for entry in self.audit_log],
        }

    @staticmethod
    def _serialize_audit_entry(entry: Dict) -> Dict:
        return {
            'timestamp': entry['timestamp'].isoformat(),
            'event_type': entry['event_type'],
            'details': entry['details'],
        }

    def load_state(self, file_path: str) -> None:
        with open(file_path, 'r', encoding=self._config.encoding) as f:
            state = json.load(f)
            self.processed_transactions = {}
            self._load_processed_transactions(state['processed_transactions'])
            self.account_balances = state['account_balances']
            self.audit_log = []
            self._load_audit_entries(state['audit_log'])

    def _load_processed_transactions(self, transactions: Dict) -> None:
        for (tx_id, tx_data) in transactions.items():
            try:
                self.processed_transactions[tx_id] = self._deserialize_transaction(tx_data)
            except Exception as e:
                self._log_audit(
                    AuditEventType.STATE_LOAD_ERROR,
                    f'Failed to load transaction {tx_id}: {str(e)}',
                )

    @staticmethod
    def _deserialize_transaction(tx_data: Dict) -> Transaction:
        tx = Transaction(
            sender=tx_data['sender'],
