            patient_id=record_data[RecordField.PATIENT_ID],
            name=record_data[RecordField.NAME],
            dob=record_data.get(RecordField.DOB, ''),
        )
        self._replace_list_field(patient, record_data, RecordField.MEDICAL_HISTORY)
        self._replace_list_field(patient, record_data, RecordField.ALLERGIES)
        self._replace_list_field(patient, record_data, RecordField.MEDICATIONS)
        self.patient_records[record_id] = patient

    @staticmethod
    def _replace_list_field(patient: PatientRecord, record_data: Dict, field: str) -> None:
        """Assign a list field verbatim when present and correctly typed."""
        if field in record_data and isinstance(record_data[field], list):
            setattr(patient, field, record_data[field])

    def _update_existing_record(self, record_id: str, record_data: Dict) -> None:
        patient = self.patient_records[record_id]
        self._merge_medical_history(patient, record_data)
        self._merge_unique_field(patient, record_data, RecordField.ALLERGIES)
        self._merge_unique_field(patient, record_data, RecordField.MEDICATIONS)

    @staticmethod
    def _merge_medical_history(patient: PatientRecord, record_data: Dict) -> None:
        field = RecordField.MEDICAL_HISTORY
        if field in record_data and isinstance(record_data[field], list):
            for entry in record_data[field]:
                if isinstance(entry, dict):
                    patient.add_medical_entry(entry)

    @staticmethod
    def _merge_unique_field(patient: PatientRecord, record_data: Dict, field: str) -> None:
        """Merge a list field with existing values, dropping duplicates."""
        if field in record_data and isinstance(record_data[field], list):
            setattr(patient, field, list(set(getattr(patient, field) + record_data[field])))

    # -- auditing ----------------------------------------------------------

    def _log_audit(self, event_type: str, details: str) -> None:
        self.audit_log.append({
            AuditKey.TIMESTAMP: datetime.datetime.now(),
            AuditKey.EVENT_TYPE: event_type,
            AuditKey.DETAILS: details,
        })

    # -- exporting / lookup ------------------------------------------------

    def export_records(self, record_ids: List[str]) -> bytes:
        export_data = {}
        for record_id in record_ids:
            if record_id in self.patient_records:
                patient = self.patient_records[record_id]
                export_data[record_id] = self._serialize_record(patient)
        return json.dumps(export_data).encode(ENCODING)

    @staticmethod
    def _serialize_record(patient: PatientRecord) -> Dict:
        return {
            RecordField.PATIENT_ID: patient.patient_id,
            RecordField.NAME: patient.name,
            RecordField.DOB: patient.dob,
            RecordField.MEDICAL_HISTORY: patient.medical_history,
            RecordField.ALLERGIES: patient.allergies,
            RecordField.MEDICATIONS: patient.medications,
            RecordField.LAST_UPDATED: patient.last_updated.isoformat(),
        }

    def get_record(self, record_id: str) -> Optional[PatientRecord]:
        return self.patient_records.get(record_id)

    def verify_record_integrity(self, record_id: str) -> bool:
        if record_id not in self.patient_records:
            return False
        patient = self.patient_records[record_id]
        return patient.record_hash == patient._calculate_hash()


