            path = self._get_save_path(game_state.player_id)
            _write_save_data(path, save_data)
            self._log_audit(AUDIT_EVENT_SAVE_SUCCESS, game_state.player_id)
            return True
        except Exception as e:
            self._log_audit(AUDIT_EVENT_SAVE_FAILED, str(e))
            return False

    def load_game(self, player_id: str) -> Optional[GameState]:
        try:
            path = self._get_save_path(player_id)
            if not os.path.exists(path):
                return None
            save_data = _read_save_data(path)
            return self._reconstruct_game_state(save_data)
        except Exception as e:
            self._log_audit(AUDIT_EVENT_LOAD_FAILED, str(e))
            return None

    def _reconstruct_game_state(self, save_data: Dict) -> GameState:
        game_state = GameState(save_data['player_id'])
        game_state.characters = save_data.get('characters', {})
        game_state.inventory = save_data.get('inventory', [])
        game_state.quests = save_data.get('quests', {})
        game_state.stats = save_data.get('stats', {})
        game_state.timestamp = save_data.get('timestamp', datetime.now())
        game_state.version = save_data.get('version', self.config.game_version)
        game_state.checksum = save_data.get('checksum', '')
        self._verify_checksum(game_state)
        self.loaded_saves[game_state.player_id] = game_state
        self._log_audit(AUDIT_EVENT_LOAD_SUCCESS, game_state.player_id)
        return game_state

    def _verify_checksum(self, game_state: GameState) -> None:
        if game_state.checksum != game_state._calculate_checksum():
            self._log_audit(AUDIT_EVENT_CHECKSUM_MISMATCH, game_state.player_id)

    def import_save_file(self, file_path: str) -> Optional[GameState]:
        try:
            save_data = _read_save_data(file_path)
            return self._reconstruct_game_state(save_data)
        except Exception as e:
            self._log_audit(AUDIT_EVENT_IMPORT_FAILED, str(e))
            return None

    def _log_audit(self, event_type: str, details: str) -> None:
        self.audit_log.append(_create_audit_entry(event_type, details))

    def get_recent_audit_logs(self, count: int=5) -> List[Dict]:
        return self.audit_log[-count:]


