KEY_TIMESTAMP = 'timestamp'
KEY_EVENT = 'event'
KEY_DETAILS = 'details'

# ---------------------------------------------------------------------------
# Messages, prompts and errors
# ---------------------------------------------------------------------------

MSG_APP_TITLE = 'Smart Home Automation System'
MSG_AUDIT_HEADER = '\nRecent audit events:'
MSG_INVALID_OPTION = 'Invalid option'
MSG_CONFIG_IMPORT_SUCCESS = 'Device config imported successfully'
MSG_CONFIG_IMPORT_FAILURE = 'Failed to import device config'
MSG_BACKUP_SUCCESS = 'Backup created successfully'
