PROMPT_DEVICE_TYPE = 'Enter device type: '
PROMPT_CONFIG_PATH = 'Enter config file path: '
PROMPT_BACKUP_FILENAME = 'Enter backup filename: '
PROMPT_MENU_CHOICE = 'Select option: '

ERROR_INVALID_DEVICE_ID = 'Invalid device ID'

