class AuditEvents:
    """Namespace grouping the audit event type identifiers."""

    DEVICE_ADDED = 'DEVICE_ADDED'
    CONFIG_IMPORT_FAILED = 'CONFIG_IMPORT_FAILED'
    CONFIG_UPDATED = 'CONFIG_UPDATED'
    BACKUP_CREATED = 'BACKUP_CREATED'
    BACKUP_FAILED = 'BACKUP_FAILED'
    SYSTEM_RESTORED = 'SYSTEM_RESTORED'
    RESTORE_FAILED = 'RESTORE_FAILED'


class SmartDevice:

    def __init__(self, device_id: str, device_type: str):
        self.device_id = device_id
        self.device_type = device_type
        self.state = DEFAULT_DEVICE_STATE
        self.last_updated = datetime.now()
        self.config = {}
        self.firmware_version = DEFAULT_FIRMWARE_VERSION

    def update_state(self, new_state: str) -> None:
        self.state = new_state
        self._touch()

    def update_config(self, config: Dict) -> None:
        self.config.update(config)
        self._touch()

    def _touch(self) -> None:
        self.last_updated = datetime.now()


class HomeAutomationHub:

    def __init__(self):
        self.devices: Dict[str, SmartDevice] = {}
        self.scenes: Dict[str, List[Dict]] = {}
        self.routines: Dict[str, Dict] = {}
        self.audit_log: List[Dict] = []
        self._ensure_backup_directory()

    @staticmethod
    def _ensure_backup_directory() -> None:
        os.makedirs(BACKUP_DIRECTORY, exist_ok=True)

    def add_device(self, device_id: str, device_type: str) -> None:
        if device_id not in self.devices:
            self.devices[device_id] = SmartDevice(device_id, device_type)
            self._log_audit(
                AuditEvents.DEVICE_ADDED,
                f'Added {device_type} with ID {device_id}',
            )

    def import_device_config(self, config_data: bytes) -> bool:
        try:
            config = self._deserialize_config(config_data)
            return self._apply_device_config(config)
        except Exception as e:
            self._log_audit(AuditEvents.CONFIG_IMPORT_FAILED, str(e))
            return False

    @staticmethod
    def _deserialize_config(config_data: bytes) -> Dict:
        return pickle.loads(config_data)

    def _apply_device_config(self, config: Dict) -> bool:
        device_id = config.get(KEY_DEVICE_ID)
        if not device_id or device_id not in self.devices:
            raise ValueError(ERROR_INVALID_DEVICE_ID)
        device = self.devices[device_id]
        if KEY_STATE in config:
            device.update_state(config[KEY_STATE])
        if KEY_CONFIG in config:
            device.update_config(config[KEY_CONFIG])
        if KEY_FIRMWARE in config:
            device.firmware_version = config[KEY_FIRMWARE]
        self._log_audit(AuditEvents.CONFIG_UPDATED, f'Updated config for {device_id}')
        return True

    def backup_system(self, filename: str) -> bool:
        try:
            self._write_backup_file(self._backup_path(filename), self._build_backup_data())
            self._log_audit(AuditEvents.BACKUP_CREATED, filename)
            return True
        except Exception as e:
            self._log_audit(AuditEvents.BACKUP_FAILED, str(e))
            return False

    def restore_backup(self, filename: str) -> bool:
        try:
            backup_data = self._read_backup_file(self._backup_path(filename))
            self._restore_devices(backup_data[KEY_DEVICES])
            self.scenes = backup_data.get(KEY_SCENES, {})
            self.routines = backup_data.get(KEY_ROUTINES, {})
            self._log_audit(AuditEvents.SYSTEM_RESTORED, filename)
            return True
        except Exception as e:
            self._log_audit(AuditEvents.RESTORE_FAILED, str(e))
            return False

    @staticmethod
    def _backup_path(filename: str) -> str:
        return os.path.join(BACKUP_DIRECTORY, filename)

    def _build_backup_data(self) -> Dict:
        return {
            KEY_DEVICES: {did: device.__dict__ for (did, device) in self.devices.items()},
            KEY_SCENES: self.scenes,
            KEY_ROUTINES: self.routines,
            KEY_TIMESTAMP: datetime.now().isoformat(),
        }

    @staticmethod
    def _write_backup_file(path: str, backup_data: Dict) -> None:
        with open(path, 'wb') as f:
            pickle.dump(backup_data, f)

    @staticmethod
    def _read_backup_file(path: str) -> Dict:
        with open(path, 'rb') as f:
            return pickle.load(f)

    def _restore_devices(self, device_states: Dict) -> None:
        self.devices.clear()
        for (did, device_data) in device_states.items():
            self.devices[did] = self._rebuild_device(did, device_data)

    @staticmethod
    def _rebuild_device(device_id: str, device_data: Dict) -> SmartDevice:
        device = SmartDevice(device_id, device_data[KEY_DEVICE_TYPE])
        device.__dict__.update(device_data)
        return device

    def _log_audit(self, event_type: str, details: str) -> None:
        self.audit_log.append(self._make_audit_entry(event_type, details))

    @staticmethod
    def _make_audit_entry(event_type: str, details: str) -> Dict:
        return {KEY_TIMESTAMP: datetime.now(), KEY_EVENT: event_type, KEY_DETAILS: details}

    def get_audit_log(self) -> List[Dict]:
        return self.audit_log[-AUDIT_LOG_TAIL_SIZE:]


