"""Smart home automation system.

A small command-line application for managing smart devices, importing
device configuration, backing up and restoring the system state, and
viewing a short audit log of recent actions.
"""

import json
import hashlib
import os
from datetime import datetime
from typing import Dict, List

# --- Default device values ----------------------------------------------------

DEFAULT_DEVICE_STATE = 'off'
DEFAULT_FIRMWARE_VERSION = '1.0.0'

# --- Persistence settings -----------------------------------------------------

BACKUP_DIRECTORY = 'backups'
FILE_ENCODING = 'utf-8'

# --- Audit log settings -------------------------------------------------------

AUDIT_LOG_ENTRY_LIMIT = 20


class AuditEvent:
    """Event names recorded in the home automation hub audit log."""

    DEVICE_ADDED = 'DEVICE_ADDED'
    CONFIG_UPDATED = 'CONFIG_UPDATED'
    CONFIG_IMPORT_FAILED = 'CONFIG_IMPORT_FAILED'
    BACKUP_CREATED = 'BACKUP_CREATED'
    BACKUP_FAILED = 'BACKUP_FAILED'
    SYSTEM_RESTORED = 'SYSTEM_RESTORED'
    RESTORE_FAILED = 'RESTORE_FAILED'


class SmartDevice:
    """A single smart device managed by the home automation hub."""

    def __init__(self, device_id: str, device_type: str):
        self.device_id = device_id
        self.device_type = device_type
        self.state = DEFAULT_DEVICE_STATE
        self.last_updated = datetime.now()
        self.config = {}
        self.firmware_version = DEFAULT_FIRMWARE_VERSION

    def update_state(self, new_state: str) -> None:
        self.state = new_state
        self._mark_updated()

    def update_config(self, config: Dict) -> None:
        self.config.update(config)
        self._mark_updated()

    def to_dict(self) -> Dict:
        return {
            'device_id': self.device_id,
            'device_type': self.device_type,
            'state': self.state,
            'last_updated': self.last_updated.isoformat(),
            'config': self.config,
            'firmware_version': self.firmware_version,
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'SmartDevice':
        device = cls(data['device_id'], data['device_type'])
        device.state = data.get('state', DEFAULT_DEVICE_STATE)
        device.last_updated = cls._parse_last_updated(data)
        device.config = data.get('config', {})
        device.firmware_version = data.get('firmware_version', DEFAULT_FIRMWARE_VERSION)
        return device

    def _mark_updated(self) -> None:
        self.last_updated = datetime.now()

    @staticmethod
    def _parse_last_updated(data: Dict) -> datetime:
        return datetime.fromisoformat(data.get('last_updated', datetime.now().isoformat()))


class HomeAutomationHub:
    """Coordinates devices, scenes, routines, backups and the audit log."""

    def __init__(self):
        self.devices: Dict[str, SmartDevice] = {}
        self.scenes: Dict[str, List[Dict]] = {}
        self.routines: Dict[str, Dict] = {}
        self.audit_log: List[Dict] = []
        os.makedirs(BACKUP_DIRECTORY, exist_ok=True)

    def add_device(self, device_id: str, device_type: str) -> None:
        if device_id not in self.devices:
            self.devices[device_id] = SmartDevice(device_id, device_type)
            self._log_audit(AuditEvent.DEVICE_ADDED, f'Added {device_type} with ID {device_id}')

    def import_device_config(self, config_data: bytes) -> bool:
        try:
            config = json.loads(config_data.decode(FILE_ENCODING))
            return self._apply_device_config(config)
        except Exception as e:
            self._log_audit(AuditEvent.CONFIG_IMPORT_FAILED, str(e))
            return False

    def _apply_device_config(self, config: Dict) -> bool:
        device_id = self._resolve_config_target(config)
        device = self.devices[device_id]
        self._apply_state_field(device, config)
        self._apply_config_field(device, config)
        self._apply_firmware_field(device, config)
        self._log_audit(AuditEvent.CONFIG_UPDATED, f'Updated config for {device_id}')
        return True

    def _resolve_config_target(self, config: Dict) -> str:
        if not isinstance(config, dict):
            raise ValueError('Config must be a dictionary')
        device_id = config.get('device_id')
        if not device_id or device_id not in self.devices:
            raise ValueError('Invalid device ID')
        return device_id

    @staticmethod
    def _apply_state_field(device: SmartDevice, config: Dict) -> None:
        if 'state' in config:
            if not isinstance(config['state'], str):
                raise ValueError('State must be a string')
            device.update_state(config['state'])

    @staticmethod
    def _apply_config_field(device: SmartDevice, config: Dict) -> None:
        if 'config' in config:
            if not isinstance(config['config'], dict):
                raise ValueError('Config must be a dictionary')
            device.update_config(config['config'])

    @staticmethod
    def _apply_firmware_field(device: SmartDevice, config: Dict) -> None:
        if 'firmware' in config:
            if not isinstance(config['firmware'], str):
                raise ValueError('Firmware must be a string')
            device.firmware_version = config['firmware']

    def backup_system(self, filename: str) -> bool:
        try:
            self._write_backup(filename, self._build_backup_data())
            self._log_audit(AuditEvent.BACKUP_CREATED, filename)
            return True
        except Exception as e:
            self._log_audit(AuditEvent.BACKUP_FAILED, str(e))
            return False

    def _build_backup_data(self) -> Dict:
        return {
            'devices': {did: device.to_dict() for (did, device) in self.devices.items()},
            'scenes': self.scenes,
            'routines': self.routines,
            'timestamp': datetime.now().isoformat(),
        }

    def _write_backup(self, filename: str, backup_data: Dict) -> None:
        with open(self._backup_path(filename), 'w', encoding=FILE_ENCODING) as f:
            json.dump(backup_data, f)

    def restore_backup(self, filename: str) -> bool:
        try:
            backup_data = self._read_backup(filename)
            self._restore_backup_data(backup_data)
            self._log_audit(AuditEvent.SYSTEM_RESTORED, filename)
            return True
        except Exception as e:
            self._log_audit(AuditEvent.RESTORE_FAILED, str(e))
            return False

    def _read_backup(self, filename: str) -> Dict:
        with open(self._backup_path(filename), 'r', encoding=FILE_ENCODING) as f:
            backup_data = json.load(f)
        if not isinstance(backup_data, dict):
            raise ValueError('Invalid backup format')
        return backup_data

    def _restore_backup_data(self, backup_data: Dict) -> None:
        self._restore_devices(backup_data.get('devices', {}))
        self.scenes = backup_data.get('scenes', {})
        self.routines = backup_data.get('routines', {})

    def _restore_devices(self, devices_data: Dict) -> None:
        self.devices.clear()
        for (did, device_data) in devices_data.items():
            if not isinstance(device_data, dict):
                raise ValueError('Invalid device format')
            self.devices[did] = SmartDevice.from_dict(device_data)

    @staticmethod
    def _backup_path(filename: str) -> str:
        return f'{BACKUP_DIRECTORY}/{filename}'

    def _log_audit(self, event_type: str, details: str) -> None:
        self.audit_log.append({'timestamp': datetime.now(), 'event': event_type, 'details': details})

    def get_audit_log(self) -> List[Dict]:
        return self.audit_log[-AUDIT_LOG_ENTRY_LIMIT:]


class SmartHomeApp:
    """Command-line front-end for the home automation hub."""

    def __init__(self):
        self.hub = HomeAutomationHub()

    def add_new_device(self) -> None:
        device_id = input('Enter device ID: ')
        device_type = input('Enter device type: ')
        self.hub.add_device(device_id, device_type)
